ALTER TABLE consult_department_keyword ADD COLUMN term_type TINYINT NOT NULL DEFAULT 1 COMMENT '1症状 2病名 3科室名' AFTER kind;
ALTER TABLE consultation_session ADD COLUMN triage_json JSON NULL COMMENT '最近一次分诊决策（归约词、挂科来源）。派医生只读这里' AFTER card_json;
ALTER TABLE safety_decision_audit ADD COLUMN certainty TINYINT NOT NULL DEFAULT 1 COMMENT '1规则明确 2规则不明确交模型' AFTER evaluation;
ALTER TABLE safety_decision_audit ADD COLUMN model_trigger_ids JSON NULL COMMENT '命中的模型触发编号。未触发为空' AFTER shadow_rule_ids;

